{
  "decisions": [
    {
      "surface": "current provision",
      "action": "create",
      "measure": "current provision",
      "description": "Represents the short-term portion of a provision."
    },
    {
      "surface": "arising during the year",
      "action": "create",
      "measure": "amount arising during the year",
      "description": "Represents the value of an obligation or asset created within the reporting period."
    },
    {
      "surface": "total amount",
      "action": "create",
      "measure": "total amount",
      "description": "A generic total amount; kept separate to avoid conflation with specific financial line items."
    },
    {
      "surface": "amount received during the year",
      "action": "create",
      "measure": "amount received during the year",
      "description": "Cash or equivalent received within the reporting period."
    },
    {
      "surface": "total finance income",
      "action": "create",
      "measure": "total finance income",
      "description": "Income generated from financial activities."
    },
    {
      "surface": "total other income",
      "action": "create",
      "measure": "total other income",
      "description": "Income outside of core operations."
    },
    {
      "surface": "loss",
      "action": "link",
      "measure": "restated loss for the period/year",
      "description": "Refers to the loss attributable to equity holders, consistent with the existing canonical measure for losses."
    },
    {
      "surface": "acquisition through business combination",
      "action": "create",
      "measure": "acquisition through business combination",
      "description": "Value of assets or liabilities acquired via business combination."
    },
    {
      "surface": "current service cost",
      "action": "create",
      "measure": "current service cost",
      "description": "The increase in the present value of the defined benefit obligation resulting from employee service in the current period."
    },
    {
      "surface": "benefits paid",
      "action": "create",
      "measure": "benefits paid",
      "description": "Payments made to employees or beneficiaries under a benefit plan."
    },
    {
      "surface": "closing defined benefit obligation",
      "action": "create",
      "measure": "closing defined benefit obligation",
      "description": "The total liability for defined benefit plans at the end of the reporting period."
    },
    {
      "surface": "actuarial gain/(loss) due to demographic assumption changes in dbo",
      "action": "create",
      "measure": "actuarial gain or loss due to demographic assumption changes in dbo",
      "description": "Specific actuarial impact on defined benefit obligations due to demographic changes."
    },
    {
      "surface": "sensitivity to 0.5% increase in future salary",
      "action": "create",
      "measure": "sensitivity to 0.5% increase in future salary",
      "description": "Impact on defined benefit obligation given a specific salary growth assumption change."
    },
    {
      "surface": "sensitivity to 0.5% decrease in future salary",
      "action": "create",
      "measure": "sensitivity to 0.5% decrease in future salary",
      "description": "Impact on defined benefit obligation given a specific salary growth assumption change."
    },
    {
      "surface": "more than 5 years",
      "action": "create",
      "measure": "expected contribution for more than 5 years",
      "description": "Long-term expected contribution to a defined benefit plan."
    },
    {
      "surface": "provision",
      "action": "create",
      "measure": "provision",
      "description": "General provision amount."
    },
    {
      "surface": "carrying amount",
      "action": "create",
      "measure": "carrying amount",
      "description": "The value at which an asset or liability is recognized in the balance sheet."
    },
    {
      "surface": "depreciation expense of right-of-use assets",
      "action": "create",
      "measure": "depreciation expense of right-of-use assets",
      "description": "Depreciation specifically related to right-of-use assets under lease accounting."
    },
    {
      "surface": "interest expense on lease liabilities",
      "action": "create",
      "measure": "interest expense on lease liabilities",
      "description": "Interest cost associated with lease liabilities."
    },
    {
      "surface": "total amount recognised in consolidated statement of profit or loss",
      "action": "create",
      "measure": "total amount recognised in consolidated statement of profit or loss",
      "description": "Aggregate expense or income recognized in the P&L statement."
    },
    {
      "surface": "contractual maturity of lease liabilities",
      "action": "create",
      "measure": "contractual maturity of lease liabilities",
      "description": "Maturity profile of lease obligations."
    },
    {
      "surface": "closing balance of lease liabilities",
      "action": "create",
      "measure": "closing balance of lease liabilities",
      "description": "Total lease liability at the end of the period."
    },
    {
      "surface": "is an associate of the group",
      "action": "create",
      "measure": "is an associate of the group",
      "description": "Status indicator for an associate entity."
    },
    {
      "surface": "acquisition consideration",
      "action": "create",
      "measure": "acquisition consideration",
      "description": "The amount paid or payable for an acquisition."
    }
  ]
}
